    double x1 = ecpt[ka+1];   // x-coordinate of pivotal node (ECPT(KA+2) -> index ka+1)
    double y1 = ecpt[ka+2];   // y-coordinate of pivotal node (ECPT(KA+3) -> index ka+2)
    double z1 = ecpt[ka+3];   // z-coordinate of pivotal node (ECPT(KA+4) -> index ka+3)
    double x2 = ecpt[kb+1];   // x-coordinate of non-pivotal node (ECPT(KB+2) -> index kb+1)
    double y2 = ecpt[kb+2];   // y-coordinate of non-pivotal node (ECPT(KB+3) -> index kb+2)
    double z2 = ecpt[kb+3];   // z-coordinate of non-pivotal node (ECPT(KB+4) -> index kb+3)

    // Compute vector from pivotal to non-pivotal node
    double x = x2 - x1;
    double y = y2 - y1;
    double z = z2 - z1;
    double xl = std::sqrt(x*x + y*y + z*z);

    // Normalize direction vector
    double xn[3];
    xn[0] = x / xl;
    xn[1] = y / xl;
    xn[2] = z / xl;

    // Compute stiffness coefficients
    double dscl = A * E / xl;  // axial stiffness coefficient
    double dscr = J * G / xl;  // torsional stiffness coefficient

    // Build N matrix (3x3 outer product of direction vector)
    // N = [xn[0]^2, xn[0]*xn[1], xn[0]*xn[2]]
    //     [xn[1]*xn[0], xn[1]^2, xn[1]*xn[2]]
    //     [xn[2]*xn[0], xn[2]*xn[1], xn[2]^2]
    double n[9];
    n[0] = xn[0] * xn[0];  // (0,0)
    n[1] = xn[0] * xn[1];  // (0,1)
    n[2] = xn[0] * xn[2];  // (0,2)
    n[3] = xn[1] * xn[0];  // (1,0)
    n[4] = xn[1] * xn[1];  // (1,1)
    n[5] = xn[1] * xn[2];  // (1,2)
    n[6] = xn[2] * xn[0];  // (2,0)
    n[7] = xn[2] * xn[1];  // (2,1)
    n[8] = xn[2] * xn[2];  // (2,2)

    // Initialize 12x12 global stiffness matrix
    Eigen::Matrix<double, 12, 12> k_global = Eigen::Matrix<double, 12, 12>::Zero();

    // Axial stiffness: couples translation DOFs (0-2 for node A, 6-8 for node B)
    // Top-left block (0:2, 0:2): dscl * N
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            k_global(i, j) = dscl * n[i*3 + j];
        }
    }

    // Top-right block (0:2, 6:8): -dscl * N
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            k_global(i, 6+j) = -dscl * n[i*3 + j];
        }
    }

    // Bottom-left block (6:8, 0:2): -dscl * N
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            k_global(6+i, j) = -dscl * n[i*3 + j];
        }
    }

    // Bottom-right block (6:8, 6:8): dscl * N
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            k_global(6+i, 6+j) = dscl * n[i*3 + j];
        }
    }

    // Torsional stiffness: couples rotational DOFs (3-5 for node A, 9-11 for node B)
    // For CROD, torsional stiffness only couples the rotations about the element axis (rx)
    // So only DOF indices 3 (rx_A) and 9 (rx_B) are affected
    // k_global(3,3) = dscr
    // k_global(3,9) = -dscr
    // k_global(9,3) = -dscr
    // k_global(9,9) = dscr
    k_global(3, 3) = dscr;
    k_global(3, 9) = -dscr;
    k_global(9, 3) = -dscr;
    k_global(9, 9) = dscr;

    return k_global;
}

// Helper function to format double in scientific notation
std::string format_double(double value) {
    std::ostringstream oss;
    oss << std::scientific << std::setprecision(15) << value;
    std::string result = oss.str();

    // Remove trailing zeros after decimal point
    size_t pos = result.find_last_not_of('0');
    if (pos != std::string::npos && result[pos] == '.') {
        result.erase(pos + 1);
    } else if (pos != std::string::npos) {
        result.erase(pos + 1);
    }

    return result;
}

int main() {
    // Compute the 12x12 stiffness matrix
    Eigen::Matrix<double, 12, 12> k_matrix = compute_crod_stiffness();

    // Output as JSON
    std::cout << "{\"stiffness_matrix\":[";

    for (int i = 0; i < 12; ++i) {
        if (i > 0) std::cout << ",";
        std::cout << "[";

        for (int j = 0; j < 12; ++j) {
            if (j > 0) std::cout << ",";
            std::cout << format_double(k_matrix(i, j));
        }

        std::cout << "]";
    }

    std::cout << "]}" << std::endl;

    return 0;
}
